<script setup lang="ts">
import {ref,reactive} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageShell from './PageShell.vue';import {usePage} from '../composables/usePage';import {request} from '../utils/request';import {categories,confirm,toast} from '../utils/format'
const id=ref(0),form=reactive({name:'',category:'CAT',breed:'',birthday:'',weight:'',temperament:'',dietaryNotes:'',medicalHistory:'',photoUrl:''});onLoad(q=>id.value=Number(q?.id||0));const {loading,error,load,busy,action}=usePage(async()=>{if(id.value){const p=(await request('/owner/pets')).find((p:any)=>p.id===id.value);if(!p)throw new Error('宠物档案不存在');Object.assign(form,{...p,dietaryNotes:p.dietary_notes||'',medicalHistory:p.medical_history||'',photoUrl:p.photo_url||'',birthday:p.birthday||'',weight:p.weight||''})}})
async function save(){if(!form.name.trim())return toast('请填写宠物名字');await request('/owner/pets'+(id.value?'/'+id.value:''),id.value?'PUT':'POST',{...form,weight:form.weight?Number(form.weight):null,birthday:form.birthday||null});uni.navigateBack()}
async function remove(){if(await confirm('确认删除该宠物档案？历史订单记录会保留。')){await request('/owner/pets/'+id.value,'DELETE');uni.navigateBack()}}
</script><template><PageShell :title="id?'宠物档案':'添加宠物'" back :loading="loading" :error="error" @retry="load"><view class="title">认识你的毛孩子</view><view class="subtitle" style="margin-bottom:20px">越了解，越能照顾好。</view><view class="tabs"><view v-for="c in ['CAT','DOG','SMALL','OTHER']" :key="c" :class="['tab',{active:form.category===c}]" @click="form.category=c">{{categories[c]}}</view></view><view class="card"><text class="label">名字 *</text><view class="field"><input v-model="form.name" placeholder="毛孩子的名字" maxlength="32"/></view><text class="label">品种</text><view class="field"><input v-model="form.breed" placeholder="例如：英短、金毛"/></view><text class="label">出生日期</text><picker mode="date" :value="form.birthday" @change="form.birthday=$event.detail.value"><view class="field" style="padding:12px">{{form.birthday||'选择日期'}}</view></picker><text class="label">体重（kg）</text><view class="field"><input v-model="form.weight" type="digit" placeholder="例如 4.5"/></view><text class="label">性格与注意事项</text><view class="field field-area"><textarea v-model="form.temperament" placeholder="怕生、喜欢的玩具…" maxlength="500"/></view><text class="label">饮食与禁忌</text><view class="field field-area"><textarea v-model="form.dietaryNotes" placeholder="每日食量、过敏食物、喂食方式"/></view><text class="label">医疗与既往病史</text><view class="field field-area"><textarea v-model="form.medicalHistory" placeholder="请如实填写，帮助喂养师安全照护"/></view><text class="label">照片地址（HTTPS）</text><view class="field"><input v-model="form.photoUrl" placeholder="可选，填写宠物照片链接"/></view></view><button class="primary" :loading="busy" :disabled="busy" @click="action(save,'档案已保存')">保存宠物档案</button><button v-if="id" class="outline full-width" style="margin-top:12px" @click="action(remove,'')">删除档案</button></PageShell></template>
